#include <cstdio>
#include <cstring>
#include <cmath>
#include <cstdlib>
#include <vector>
#include <string>
#include <algorithm>
#include <queue>
#include <stack>
#include <deque>
#include <map>
#include <set>
#include <unordered_map>
#include <unordered_set>
#include <functional>
#include <numeric>
#include <sstream>
#include <iostream>
using namespace std;
int main(){int n,m,k;scanf("%d %d %d",&n,&m,&k);
vector<long long>a(n),b(m);
for(int i=0;i<n;++i)scanf("%lld",&a[i]);
for(int i=0;i<m;++i)scanf("%lld",&b[i]);
priority_queue<pair<long long,pair<int,int>>>pq;
for(int i=0;i<min(n,k);++i)for(int j=0;j<min(m,k);++j){
pq.push({a[i]+b[j],{i,j}});          // 大根堆：堆顶是当前和最大的
if((int)pq.size()>k)pq.pop();        // 弹掉和最大的，保留和最小的 k 个
}
vector<pair<long long,pair<int,int>>>res;
while(!pq.empty()){res.push_back(pq.top());pq.pop();}
reverse(res.begin(),res.end());
for(auto&pr:res)printf("%d %d\n",pr.second.first,pr.second.second);
return 0;}

